import re
ttl = open(GRAPH_TTL).read()
prefixes = {
 'bldg':'http://buildgraph.org/BG_large_office_2004_0000#',
 'brick':'https://brickschema.org/schema/Brick#',
 'meta':'https://buildgraph.org/meta#',
 'owl':'http://www.w3.org/2002/07/owl#',
 'quantitykind':'http://qudt.org/vocab/quantitykind/',
 'qudt':'http://qudt.org/schema/qudt/',
 'rdfs':'http://www.w3.org/2000/01/rdf-schema#',
 'ref':'https://brickschema.org/schema/Brick/ref#',
 'unit':'http://qudt.org/vocab/unit/',
 'xsd':'http://www.w3.org/2001/XMLSchema#',
}
def q(term):
    term=term.strip()
    if term.startswith('<') and term.endswith('>'):
        return term[1:-1]
    if ':' in term and not term.startswith('<'):
        p,l=term.split(':',1)
        if p in prefixes:
            return prefixes[p]+l
        # could be xsd datatype suffix - skip
    return term

triples=[]
for line in ttl.split('\n'):
    line=line.strip()
    if not line or line.startswith('@prefix'):
        continue
    # strip trailing .
    line=line.rstrip('.').strip()
    # split by ;
    parts=re.split(r';\s*', line)
    subject=parts[0].split()[0]
    if subject.endswith('.'):
        subject=subject[:-1]
    subj=q(subject)
    for part in parts:
        part=part.strip()
        # split predicate object(s)
        toks=part.split()
        if not toks:
            continue
        if toks[0]==subj:
            toks=toks[1:]
        if not toks:
            continue
        pred=toks[0]
        if pred in ('a',):
            pred='http://www.w3.org/1999/02/22-rdf-syntax-ns#type'
        obj=toks[1] if len(toks)>1 else None
        if obj is not None and obj.endswith(('{','[','(',')')):
            obj=obj[:-1]
        if obj and obj.strip():
            triples.append((subj,q(pred),q(obj)))
print(len(triples))

base='http://buildgraph.org/BG_large_office_2004_0000#'
def find(pred, contains=None):
    out=[]
    for s,p,o in triples:
        if q(pred)==p or (pred==p):
            if contains is None or contains in (s+o):
                out.append((s,o))
    return out

# get a triple
# Check: zones fed by AHU03
ahu3=base+'AHU03'
feeds=[o for s,p,o in triples if s==ahu3 and 'feeds' in p]
print("feeds:",feeds)

